/// Notes block of the contact page (`ModuleNotesViewHelper`). The emotions
/// of the note form come from `listEmotions`.
#[derive(Serialize, ToSchema)]
pub struct NotesModule {
    /// The 3 newest notes, as `listContactNotes?per_page=3`.
    pub notes: Vec<Note>,
    /// Computed number of notes of the contact.
    pub total: i64,
}

/// `ModuleNotesViewHelper::data`: the 3 newest notes and how many there are.
pub async fn notes_module(state: &AppState, ctx: &ModuleContext) -> ApiResult<NotesModule> {
    let rows = newest_first(ctx.contact.id).paginate(&state.db, 3).fetch_page(0).await?;
    let total = notes::Entity::find().filter(notes::Column::ContactId.eq(ctx.contact.id)).count(&state.db).await?;
    Ok(NotesModule {
        notes: Note::load_many(&state.db, ctx.vault.id, rows).await?,
        total: i64::try_from(total).unwrap_or(i64::MAX),
    })
}

/// `$contact->notes()->orderBy('created_at', 'desc')`.
fn newest_first(contact_id: Uuid) -> sea_orm::Select<notes::Entity> {
    notes::Entity::find()
        .filter(notes::Column::ContactId.eq(contact_id))
        .order_by_desc(notes::Column::CreatedAt)
        .order_by_desc(notes::Column::Id)
}

/// `page`/`per_page` of a list query as [`PageQuery`].
pub(super) fn page_query(page: Option<i64>, per_page: Option<i64>) -> PageQuery {
    let positive = |v: i64| u64::try_from(v.max(1)).unwrap_or(1);
    PageQuery { page: page.map(positive), per_page: per_page.map(positive) }
}

async fn note_of(state: &AppState, contact_id: Uuid, note_id: Id) -> ApiResult<notes::Model> {
    notes::Entity::find_by_id(note_id)
        .filter(notes::Column::ContactId.eq(contact_id))
        .one(&state.db)
        .await?
        .ok_or_else(ApiError::not_found)
}

/// The note fields' rules: `title` nullable|max:255, `body`
/// required|max:65535, `emotion_id` one of the account's emotions.
async fn validate(
    state: &AppState,
    account_id: Uuid,
    title: Option<&str>,
    body: Option<&str>,
    emotion_id: Option<Id>,
) -> ApiResult<()> {
    let mut v = Validator::new();
    v.max_len("title", title, 255);
    if v.required("body", &body) {
        v.max_len("body", body, 65535);
    }
    if let Some(e) = emotion_id
        && emotions::Entity::find_by_id(e)
            .filter(emotions::Column::AccountId.eq(account_id))
            .one(&state.db)
            .await?
            .is_none()
    {
        v.fail("emotion_id", "exists", &[]);
    }
    v.finish()
}

