#[utoipa::path(
    post,
    path = "/vaults/{vault_id}/contacts/{contact_id}/notes",
    operation_id = "createContactNote",
    tag = "Contact modules",
    summary = "Add a note to a contact",
    params(("vault_id" = uuid::Uuid, Path), ("contact_id" = uuid::Uuid, Path)),
    request_body = NoteCreate,
    responses((status = 201, description = "The created note.", body = Note), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`)."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("vault:edit")), ("x-inventory" = json!(["R066"])), ("x-services" = json!(["CreateNote"])))
)]
pub async fn create_contact_note(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, contact_id)): Path<(Uuid, Uuid)>,
    Json(body): Json<NoteCreate>,
) -> ApiResult<(StatusCode, Json<Note>)> {
    access::vault(&state, &id, vault_id, crate::domains::base::VaultPermission::Edit).await?;
    let contact = contact_in_vault(&state.db, vault_id, contact_id).await?;
    let title = clean(body.title);
    let text = clean(body.body);
    let emotion_id = body.emotion_id.map(Id);
    validate(&state, id.user.account_id, title.as_deref(), text.as_deref(), emotion_id).await?;
    let tx = state.db.begin().await?;
    let note = CreateNote {
        account_id: id.user.account_id,
        vault_id,
        author_id: id.user.id,
        contact_id: contact.id,
        emotion_id,
        title,
        body: text.unwrap_or_default(),
    }
    .execute(&tx)
    .await?;
    tx.commit().await?;
    Ok((StatusCode::CREATED, Json(Note::load(&state.db, vault_id, note).await?)))
}

#[utoipa::path(
    patch,
    path = "/vaults/{vault_id}/contacts/{contact_id}/notes/{note_id}",
    operation_id = "updateContactNote",
    tag = "Contact modules",
    summary = "Edit a note",
    params(("vault_id" = uuid::Uuid, Path), ("contact_id" = uuid::Uuid, Path), ("note_id" = i64, Path)),
    request_body = NoteUpdate,
    responses((status = 200, description = "The updated note.", body = Note), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`)."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("vault:edit")), ("x-inventory" = json!(["R067"])), ("x-services" = json!(["UpdateNote"])))
)]
pub async fn update_contact_note(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, contact_id, note_id)): Path<(Uuid, Uuid, Id)>,
    Json(body): Json<NoteUpdate>,
) -> ApiResult<Json<Note>> {
    access::vault(&state, &id, vault_id, crate::domains::base::VaultPermission::Edit).await?;
    let contact = contact_in_vault(&state.db, vault_id, contact_id).await?;
    let note = note_of(&state, contact.id, note_id).await?;
    let title = match body.title {
        Some(t) => clean(t),
        None => note.title.clone(),
    };
    let text = match body.body {
        Some(b) => clean(Some(b)),
        None => Some(note.body.clone()),
    };
    let emotion_id = match body.emotion_id {
        Some(e) => e.map(Id),
        None => note.emotion_id,
    };
    validate(&state, id.user.account_id, title.as_deref(), text.as_deref(), emotion_id).await?;
    let tx = state.db.begin().await?;
    let note = UpdateNote {
        account_id: id.user.account_id,
        vault_id,
        author_id: id.user.id,
        contact_id: contact.id,
        note_id: note.id,
        emotion_id,
        title,
        body: text.unwrap_or_default(),
    }
    .execute(&tx)
    .await?;
    tx.commit().await?;
    Ok(Json(Note::load(&state.db, vault_id, note).await?))
}

