pub async fn delete_contact_note(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, contact_id, note_id)): Path<(Uuid, Uuid, Id)>,
) -> ApiResult<StatusCode> {
    access::vault(&state, &id, vault_id, crate::domains::base::VaultPermission::Edit).await?;
    let contact = contact_in_vault(&state.db, vault_id, contact_id).await?;
    let note = note_of(&state, contact.id, note_id).await?;
    let tx = state.db.begin().await?;
    DestroyNote {
        account_id: id.user.account_id,
        vault_id,
        author_id: id.user.id,
        contact_id: contact.id,
        note_id: note.id,
    }
    .execute(&tx)
    .await?;
    tx.commit().await?;
    Ok(StatusCode::NO_CONTENT)
}

